779	Status CollectionImpl::Optimize(const OptimizeOptions &options) {
780	  CHECK_COLLECTION_READONLY_RETURN_STATUS;
781	
782	  std::lock_guard lock(schema_handle_mtx_);
783	  // when optimizing, schema operations(include another optimize) are not
784	  // allowed
785	
786	  CHECK_DESTROY_RETURN_STATUS(destroyed_, false);
787	
788	  std::vector<Segment::Ptr> persist_segments;
789	
790	  {
791	    // forbidden writing for a while
792	    std::lock_guard write_lock(write_mtx_);
793	
794	    if (writing_segment_->doc_count() != 0) {
795	      // flush and create new segment
796	      auto s = switch_to_new_segment_for_writing();
797	      if (!s.ok()) {
798	        return s;
799	      }
800	    }
801	
802	    persist_segments =
803	        get_all_persist_segments();  // will not return writing segment
804	    // after leave this scope, writing action is allowed
805	  }
806	
807	  if (persist_segments.size() == 0) {
808	    // no need to optimize
809	    return Status::OK();
810	  }
811	
812	  // build segment compact task
813	  auto delete_store_clone = delete_store_->clone();
814	  auto tasks =
815	      build_compact_task(schema_, persist_segments, options.concurrency_,
816	                         delete_store_clone->make_filter());
817	
818	  // execute segment compact task
819	  auto s = execute_compact_task(tasks);
820	  CHECK_RETURN_STATUS(s);
821	
822	  {
823	    // forbidden writing for updating version
824	    // writing action may trigger updating version where confict occurs
825	    std::lock_guard write_lock(write_mtx_);
826	
827	    Version new_version = version_manager_->get_current_version();
828	
829	    for (auto &task : tasks) {
830	      auto task_info = task->task_info();
831	
832	      if (std::holds_alternative<CompactTask>(task_info)) {
833	        auto compact_task = std::get<CompactTask>(task_info);
834	
835	        // 0. check if has output segment meta
836	        if (compact_task.output_segment_meta_) {
837	          // 1. rename built tmp segments
838	          auto tmp_segment_id = compact_task.output_segment_id_;
839	          auto tmp_segment_path =
840	              FileHelper::MakeTempSegmentPath(path_, tmp_segment_id);
841	
842	          auto new_segment_id = allocate_segment_id();
843	          auto new_segment_path =
844	              FileHelper::MakeSegmentPath(path_, new_segment_id);
845	
846	          if (!FileHelper::MoveDirectory(tmp_segment_path, new_segment_path)) {
847	            return Status::InternalError("move segment directory failed");
848	          }
849	
850	          // update output_segment_meta_'s segment id
851	          compact_task.output_segment_meta_->set_id(new_segment_id);
852	
853	          s = new_version.add_persisted_segment_meta(
854	              compact_task.output_segment_meta_);
855	          CHECK_RETURN_STATUS(s);
856	          new_version.set_next_segment_id(segment_id_allocator_.load());
857	        }
858	
859	        for (auto input_segment : compact_task.input_segments_) {
860	          s = new_version.remove_persisted_segment_meta(input_segment->id());
861	          CHECK_RETURN_STATUS(s);
862	        }
863	      } else if (std::holds_alternative<CreateVectorIndexTask>(task_info)) {
864	        auto create_index_task = std::get<CreateVectorIndexTask>(task_info);
865	        s = new_version.update_persisted_segment_meta(
866	            create_index_task.output_segment_meta_);
867	        CHECK_RETURN_STATUS(s);
868	      }
869	    }
870	
871	    // 2. update version
872	    s = version_manager_->apply(new_version);
873	    CHECK_RETURN_STATUS(s);
874	
875	    // 3. persist version
876	    s = version_manager_->flush();
877	    CHECK_RETURN_STATUS(s);
878	
879	    // 4. remove old segments or block
880	    for (auto &task : tasks) {
881	      auto task_info = task->task_info();
882	
883	      if (std::holds_alternative<CompactTask>(task_info)) {
884	        auto compact_task = std::get<CompactTask>(task_info);
885	
886	        if (compact_task.output_segment_meta_) {
887	          auto new_segment =
888	              Segment::Open(path_, *schema_, *compact_task.output_segment_meta_,
889	                            id_map_, delete_store_, version_manager_,
890	                            SegmentOptions{true, options_.enable_mmap_});
891	          if (!new_segment.has_value()) {
892	            return new_segment.error();
893	          }
894	          s = segment_manager_->add_segment(new_segment.value());
895	          CHECK_RETURN_STATUS(s);
896	        }
897	
898	        for (auto input_segment : compact_task.input_segments_) {
899	          s = segment_manager_->destroy_segment(input_segment->id());

file.content:
  for (auto &segment : segments) {
    stats.doc_count += segment->doc_count(delete_store_->make_filter());
  }

  for (auto &field : vector_fields) {
    if (stats.doc_count == 0) {
      stats.index_completeness[field->name()] = 1;
      continue;
    }

    uint32_t indexed_doc_count{0};
    for (auto &segment : segments) {
      if (segment->meta()->vector_indexed(field->name())) {
        indexed_doc_count += segment->doc_count(delete_store_->make_filter());
      }
    }
    stats.index_completeness[field->name()] =
        indexed_doc_count * 1.0 / stats.doc_count;
  }

  return stats;
}

